        /// <remarks>
        ///   <para>
        ///     The returned handle carries its own reference; Dispose it once when you're done.
        ///   </para>
        /// </remarks>
        public TwoBodyConstraint GetConstraint(int constraintIndex)
        {
            var _result = Jolt.PInvoke.Ragdoll_GetConstraint(this, constraintIndex, out var _inRange);
            if (_inRange == 0)
                throw new ArgumentOutOfRangeException(
                    nameof(constraintIndex),
                    constraintIndex,
                    "Expected an index below the number of constraints."
                );
            return _result;
        }

